<script setup>import {watch,onMounted,onBeforeUnmount} from 'vue';import {session} from '../services/api.js';import {notifications,refreshUnread} from '../services/notifications.js';let timer;const refresh=()=>{if(session.token&&!document.hidden)refreshUnread()};watch(()=>session.user?.id,refresh);onMounted(()=>{refresh();timer=setInterval(refresh,30000)});onBeforeUnmount(()=>clearInterval(timer));</script><template><RouterLink v-if="session.token" to="/account/notifications" :aria-label="'Thông báo: '+(notifications.count??'chưa tải')+' chưa đọc'">Thông báo<span v-if="notifications.count!==null"> ({{notifications.count}})</span><span v-if="notifications.error"> · chưa tải</span></RouterLink></template>
